// Build AI tutor prompt based on mode and context
const params = $input.first().json;

// Define tutor personality and expertise
const systemPrompt = `You are an expert debate coach and tutor for the Arena debate platform. Your role is to help users improve their debating skills through practice, feedback, and guidance.

Your expertise includes:
- Constructing strong arguments
- Finding logical fallacies
- Researching and citing evidence
- Effective rebuttal techniques
- Public speaking and persuasion
- Debate strategy and tactics

You are encouraging, patient, and provide constructive feedback. You adapt your teaching style to the user's skill level.`;

let userPrompt = '';
let conversationContext = '';

// Build context based on skill level
const skillContext = {
  beginner: 'Focus on basic concepts, simple explanations, and encouragement. Avoid jargon.',
  intermediate: 'Provide moderate complexity with some technical terms. Challenge them to think deeper.',
  advanced: 'Use advanced techniques, complex scenarios, and expect high-level analysis.'
};

conversationContext += `\nUser Skill Level: ${params.skillLevel} - ${skillContext[params.skillLevel] || skillContext.intermediate}`;

// Build prompt based on tutor mode
switch(params.tutorMode) {
  case 'practice':
    // Practice mode: AI acts as opponent
    userPrompt = `You are helping a ${params.skillLevel} debater practice.

Topic: ${params.topic || 'No topic specified yet'}
User's Position: ${params.position}

User says: "${params.userMessage}"

Provide:
1. A brief response as if you're debating against them (opposing position)
2. Constructive feedback on their argument (strengths and areas to improve)
3. A follow-up question or challenge to help them develop their thinking

Keep responses concise (3-4 paragraphs max) to maintain conversation flow.`;
    break;

  case 'critique':
    // Critique mode: Analyze user's argument
    userPrompt = `Analyze this ${params.skillLevel} debater's argument:

Topic: ${params.topic}
Position: ${params.position}
Argument: "${params.userMessage}"

Provide detailed feedback on:
1. **Strength of Logic** - Is the reasoning sound?
2. **Evidence Quality** - Do they need better sources?
3. **Persuasiveness** - How convincing is it?
4. **Potential Weaknesses** - What could opponents attack?
5. **Improvement Suggestions** - Specific ways to strengthen this argument

Be honest but encouraging.`;
    break;

  case 'research':
    // Research mode: Help find arguments
    userPrompt = `Help a ${params.skillLevel} debater research arguments.

Topic: ${params.topic}
Position: ${params.position}
User's Question: "${params.userMessage}"

Provide:
1. 3-4 strong arguments for their position
2. Key evidence points they should research
3. Potential counterarguments they'll face
4. Strategic advice for this topic

Format as a clear, actionable guide.`;
    break;

  case 'strategy':
    // Strategy mode: Debate tactics and approach
    userPrompt = `Provide debate strategy coaching for a ${params.skillLevel} debater.

Topic: ${params.topic}
User's Position: ${params.position}
User's Question: "${params.userMessage}"

Provide strategic advice on:
1. Opening strategy - How to frame the debate
2. Key arguments to prioritize
3. Opponent's likely tactics
4. Rebuttal strategy
5. Closing argument approach

Be tactical and specific.`;
    break;

  case 'tips':
    // General tips and guidance
    userPrompt = `Provide debate tips and guidance.

User's Skill Level: ${params.skillLevel}
User's Question: "${params.userMessage || 'How can I improve my debating skills?'}"

Provide:
1. Specific, actionable tips
2. Common mistakes to avoid
3. Practice exercises they can do
4. Resources or techniques to study

Keep it practical and encouraging.`;
    break;

  case 'fallacies':
    // Teach logical fallacies
    userPrompt = `Help identify and explain logical fallacies.

User's Text: "${params.userMessage}"

Analyze this statement and:
1. Identify any logical fallacies present
2. Explain why they're fallacies
3. Show how to fix or avoid them
4. Provide a stronger version of the argument

Be educational and clear for a ${params.skillLevel} level.`;
    break;

  default:
    // General conversation mode
    userPrompt = `You are a debate tutor having a conversation with a ${params.skillLevel} student.

Topic: ${params.topic || 'General debate coaching'}
Student says: "${params.userMessage}"

Respond as a helpful, encouraging debate coach. Provide guidance, answer questions, and help them improve.`;
}

return {
  json: {
    systemPrompt: systemPrompt + conversationContext,
    userPrompt: userPrompt,
    userId: params.userId,
    sessionId: params.sessionId,
    tutorMode: params.tutorMode,
    topic: params.topic,
    position: params.position,
    skillLevel: params.skillLevel
  }
};

// Format tutor response for Flutter app
const ollamaResponse = $input.first().json;
const promptData = $('Build Tutor Prompt').item.json;

// Extract AI tutor response
const tutorResponse = ollamaResponse.message?.content || 'I apologize, but I could not generate a response. Please try again.';

// Format for Flutter
return {
  json: {
    success: true,
    tutorResponse: tutorResponse,
    sessionId: promptData.sessionId,
    userId: promptData.userId,
    tutorMode: promptData.tutorMode,
    topic: promptData.topic,
    position: promptData.position,
    skillLevel: promptData.skillLevel,
    timestamp: new Date().toISOString(),
    model: 'llama3.2:3b'
  }
};
